var s=UnityEngine.SceneManagement.SceneManager.GetActiveScene();return new{playing=UnityEditor.EditorApplication.isPlaying,scene=s.path,dirty=s.isDirty,camera=new{position=Camera.main.transform.position.ToString(),rotation=Camera.main.transform.eulerAngles.ToString(),size=Camera.main.orthographicSize},lights=Resources.FindObjectsOfTypeAll<Light>().Where(l=>l.gameObject.scene==s).Select(l=>new{l.name,active=l.gameObject.activeInHierarchy,l.enabled,l.intensity,type=l.type.ToString(),parent=l.transform.parent==null?"":l.transform.parent.name}).ToArray()};
